#!/usr/bin/env bash
set -euo pipefail

MODEL="${MODEL:-}"
if [[ -z "$MODEL" ]]; then
  echo "❌ MODEL is not set. Export it before running:" >&2
  echo '   export MODEL="HiDream-ai/HiDream-O1-Image"' >&2
  exit 1
fi

# Static: model that wrote every prompt in this file (goes into the turbo negative_prompt)
GEN_MODEL="Claude Sonnet 5.5 high"

# ---- HELPERS ---------------------------------------------------------------
urlencode() {
  local string="$1" encoded="" i char
  for (( i=0; i<${#string}; i++ )); do
    char="${string:i:1}"
    case "$char" in
      [a-zA-Z0-9._~-]) encoded+="$char" ;;
      *) printf -v encoded '%s%%%02X' "$encoded" "'$char" ;;
    esac
  done
  printf '%s' "$encoded"
}

# queue_job INDEX PROMPT GENERATOR_MODEL TITLE [CONTEST]
# Negative prompt logic (turbo / distilled models):
#   CFG in 0..1 (or GUIDANCESCALE <= 1) -> negative_prompt carries metadata tags:
#                                         <Prompt generated by ..><Bounty/Crucible: ..><Title: "..">
#   otherwise                            -> negative_prompt is an empty string
queue_job() {
  local index="$1"
  local prompt="$2"
  local gen_model="$3"
  local title="$4"
  local contest="${5:-}"
  local task_name
  task_name="$(printf '%02d' "$index") ${prompt:0:16}"

  printf "[QUEUE %02d] %s…\n" "$index" "${prompt:0:120}"

  local neg_prompt=""
  local turbo=0
  if (( $(echo "$CFG >= 0 && $CFG <= 1" | bc -l) )); then turbo=1; fi
  if [[ -n "${GUIDANCESCALE:-}" ]] && (( $(echo "$GUIDANCESCALE <= 1" | bc -l) )); then turbo=1; fi
  if (( turbo )); then
    neg_prompt="<Prompt generated by ${gen_model}>"
    if [[ -n "$contest" ]]; then
      neg_prompt+="<${contest}>"
    fi
    neg_prompt+="<Title: \"${title}\">"
  fi

  local json
  json=$(jq -n \
    --arg  prompt   "$prompt"   \
    --arg  neg      "$neg_prompt" \
    --arg  sampler  "$SAMPLER"  \
    --arg  model    "$MODEL"    \
    --argjson steps  $STEPS     \
    --argjson cfg    $CFG       \
    --argjson ag     $AG        \
    --arg gnm        "$GUIDANCENAME" \
    --argjson gsc    $GUIDANCESCALE \
    --argjson w      $WIDTH     \
    --argjson h      $HEIGHT    \
    --argjson seed   $SEED      \
    '{
      sd_model_checkpoint: $model,
      checkpoint:           $model,
      prompt:               $prompt,
      negative_prompt:      $neg,
      steps:                $steps,
      cfg_scale:            $cfg,
      cfg_true:             $ag,
      guidance_name:        $gnm,
      guidance_scale:       $gsc,
      width:                $w,
      height:               $h,
      sampler_name:         $sampler,
      seed:                 $seed,
      batch_size:           1,
      n_iter:               1,
      save_images:          true
    }')

  curl -s -X POST "$SCHED?name=$(urlencode "$task_name")" \
    -H "Content-Type: application/json" \
    -d "$json" > /dev/null
}

# ---- PROMPTS ---------------------------------------------------------------
# November 2026 Civitai challenges - five prompt lists in one run
# Structure: Legs and Feet 15 + Insects 5 + Statues/Mannequins/Dolls 18
#            + Ordinary Jobs 10 + Less Is More 10 = 58 tasks total
# All prompts: Claude Sonnet 5.5 high (static GEN_MODEL above).
# Turbo runs (CFG 0..1): negative_prompt = <Prompt generated by ..><Bounty|Crucible: name><Title: "..">
# Aspect ratios are given in the titles; WIDTH/HEIGHT come from the environment.
# ---------------------------------------------------------------------------


